function fusionMaterialFits(card,u,chosen=fusionMaterials){if(!u||u.row===null||chosen.some(x=>x.id===u.id))return false;let abyssMaterial=card.materials?.archetype==='abyss',enemyAllowed=abyssMaterial&&u.owner!==state.current&&state.players[state.current].units.some(d=>hasEffect(d,'devotee')&&adjacent(d,u));if(u.owner!==state.current&&!enemyAllowed)return false;if(card.materials?.requirements){let open=card.materials.requirements.filter(req=>!chosen.some(x=>req.kind?x.kind===req.kind:x.types.includes(req.type)));if(!open.some(req=>req.kind?u.kind===req.kind:u.types.includes(req.type)))return false}else if(card.materials?.kinds&&(!card.materials.kinds.includes(u.kind)||chosen.some(x=>x.kind===u.kind)))return false;else if(card.materials?.type&&!u.types.includes(card.materials.type))return false;else if(abyssMaterial&&archetypeOfUnit(u)!=='abyss'&&!enemyAllowed)return false;return !chosen.length||chosen.some(x=>fusionLinked(x,u))}
