function resolveCombination(f,parts,pos,p,version){if(version!==gameVersion)return;clearAnimationMarks(parts);if(hasEffect(f,'amalgam')){f.atk=parts.reduce((sum,u)=>sum+effectiveAtk(u,false),0);f.movement=[...new Map(parts.flatMap(rawMovementOffsets).map(offset=>[offset.join(','),offset])).values()];f.fusion=parts.length}for(let owner of[1,2])state.players[owner].units=state.players[owner].units.filter(u=>!parts.some(x=>x.id===u.id));p.reserve=p.reserve.filter(u=>u.id!==f.id);f.combinedEntry=true;place(f,pos.row,pos.col);p.units.push(f);state.animating=false;clearAction();selected=f;log(`${f.name} foi criado em ${boardCoordinate(pos.row,pos.col)} ao combinar ${parts.length} materiais ${state.arena==='project'?'em contato ou dentro de seus raios':'em contato'}.`);render();if(hasEffect(f,'sun'))triggerSolarVictory(f.owner);else checkWin();if(onlineMode)syncOnlineState();setTimeout(()=>{if(version!==gameVersion)return;f.combinedEntry=false;renderBoard()},720)}
function completeSolarFusion(f,parts){let p=state.players[state.current],opponent=state.current===1?2:1,pos={row:parts[0].row,col:parts[0].col},version=gameVersion,ordered=(f.materials?.kinds||[]).map(kind=>parts.find(u=>u.kind===kind)).filter(Boolean),absorbStep=300;state.animating=true;clearAction();selected=f;ordered.forEach((u,index)=>{u.solarAbsorbing=true;u.solarDelay=index*absorbStep;u.combineDx=pos.col-u.col;u.combineDy=pos.row-u.row});render();hint('Os oito astros estão convergindo para formar o SOL…');if(onlineMode)syncOnlineAnimationState();setTimeout(()=>{if(version!==gameVersion)return;clearAnimationMarks(parts);p.units=p.units.filter(u=>!parts.some(x=>x.id===u.id));p.reserve=p.reserve.filter(u=>u.id!==f.id);f.solarBirth=true;place(f,pos.row,pos.col);p.units.push(f);selected=f;log(`${f.name} nasceu em ${boardCoordinate(pos.row,pos.col)} após absorver os oito astros, um a um.`);render();if(onlineMode)syncOnlineAnimationState();setTimeout(()=>{if(version!==gameVersion)return;delete f.solarBirth;let defeated=state.players[opponent].units.filter(u=>u.row!==null);defeated.forEach((u,index)=>{u.solarEvaporating=true;u.solarEvaporateDelay=index*90});hint('A luz do SOL está evaporando todos os peões adversários…');render();if(onlineMode)syncOnlineAnimationState();setTimeout(()=>{if(version!==gameVersion)return;state.players[opponent].units=state.players[opponent].units.filter(u=>u.row===null);clearAnimationMarks([f,...defeated]);state.animating=false;clearAction();selected=f;triggerSolarVictory(f.owner);if(onlineMode)syncOnlineState(true)},900+defeated.length*90)},900)},ordered.length*absorbStep+640)}
