 if(hasEffect(selected,'serpent')){mode='serpent';targets=[];for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++)if(!at(r,c)&&!featureAt(r,c)&&!pitAt(r,c))targets.push({r,c});hint('Escolha qualquer casa livre para criar o obstáculo NATURAL.')}else if(selected.kind==='jester'&&!selected.copiedKind){mode='copy';targets=allUnits().filter(u=>u.id!==selected.id&&u.row!==null).map(u=>({r:u.row,c:u.col}));hint('Escolha qualquer peão em campo para copiar seu efeito até o fim da partida.')}else if(hasEffect(selected,'rider')){mode='mount';targets=state.players[state.current].units.filter(u=>u.id!==selected.id&&effectContact(selected,u)&&archetypeOfUnit(u)==='wild'&&!u.mounted).map(u=>({r:u.row,c:u.col}));hint(`Escolha um aliado Selvagem ${state.arena==='project'?'em seu raio':'adjacente'} para montar.`)}else if(hasEffect(selected,'neptune'))return beginNeptuneAbility(selected);else if(hasEffect(selected,'monkey')){mode='monkey-pawn';targets=state.players[state.current].units.filter(u=>u.id!==selected.id&&u.types.includes('NATURAL')&&effectContact(selected,u)).map(u=>({r:u.row,c:u.col}));hint('Escolha um aliado NATURAL em contato.')}else if(hasEffect(selected,'impoluto')){if(effectiveAtk(selected,false)<100)return hint('Impoluto precisa ter ao menos 100 ATK para usar a habilidade.');mode='impoluto';targets=allUnits().filter(u=>u.id!==selected.id&&inMovementRadius(selected,u)).map(u=>({r:u.row,c:u.col}));hint('Escolha outro peão dentro do raio para receber 200 ATK.')}else if(hasEffect(selected,'atra')){mode='atra-sacrifice';targets=state.players[state.current].units.filter(u=>u.id!==selected.id&&inMovementRadius(selected,u)).map(u=>({r:u.row,c:u.col}));hint('Escolha um aliado no raio para sacrificar.')}else return hint(selected.kind==='jester'?'O Bobo já mantém o efeito copiado até o fim da partida.':'A habilidade deste peão é automática.');if(!targets.length){clearAction();return hint('Não há um alvo válido para esta habilidade.')}renderBoard()
