function clearJungleFeatures(){let before=state.obstacles.length;state.obstacles=state.obstacles.filter(feature=>feature.source!=='jungle');let removed=before-state.obstacles.length;if(removed)log(`A Selva Selvagem saiu de campo e removeu ${removed} obstáculo${removed>1?'s':''} ou fruta${removed>1?'s':''}.`)}
